import { runAll } from '/tmp/difftest.mjs';

const D = (n, d = '1') => d.repeat(n);

const cases = [];
// --- very long single integer literals in --c ---
for (const n of [100, 1000, 4299, 4300, 4301, 5000, 10000]) {
  cases.push(['--a', 'bc', '--b', '1', '--c', D(n)]);
  cases.push(['--a', 'bc', '--b', '1', '--c', '-' + D(n, '9')]);
  cases.push(['--a', 'bc', '--b', '1', '--c', '0,' + D(n) + ',0']);
  cases.push(['--a', 'bc', '--b', '1', '--c', D(n, '0')]); // all zeros -> value 0
  cases.push(['--a', 'bc', '--b', '1', '--c', '+' + D(n)]);
  cases.push(['--a', 'bc', '--b', '1', '--c', D(n) + 'x']); // invalid literal, long repr
}
// --- very long single integer literals in --b ---
for (const n of [100, 1000, 4299, 4300, 4301, 5000, 10000]) {
  cases.push(['--a', 'bc', '--b', D(n), '--c', '0,0']);
  cases.push(['--a', 'bc', '--b', '-' + D(n, '9'), '--c', '0,0']);
  cases.push(['--a', 'bc', '--b', D(n, '0'), '--c', '0,0']); // zeros -> witver 0
  cases.push(['--a', 'bc', '--b', D(n) + 'x', '--c', '0,0']);
}
// underscore separators at scale (Python allows 1_000)
cases.push(['--a', 'bc', '--b', '1', '--c', '1' + '_1'.repeat(2200)]);
cases.push(['--a', 'bc', '--b', '1', '--c', '1' + '_1'.repeat(2100)]);
cases.push(['--a', 'bc', '--b', '1' + '_1'.repeat(2200), '--c', '0,0']);
// whitespace padded huge literal
cases.push(['--a', 'bc', '--b', '1', '--c', '  ' + D(4301) + '  ']);
cases.push(['--a', 'bc', '--b', ' ' + D(4301) + ' ', '--c', '0,0']);

await runAll(cases, { label: 'stress-bigints' });

import { runCase } from '/tmp/difftest.mjs';

const CONC = Number(process.env.DIFF_CONCURRENCY || 4);

const sig = (s, n = 70) =>
  s.length <= n ? JSON.stringify(s) : JSON.stringify(s.slice(0, 40)) + `+<${s.length - 40} more chars>`;

export async function runCompact(cases, label) {
  const fails = [];
  let pass = 0, next = 0;
  async function worker() {
    while (next < cases.length) {
      const i = next++;
      let r;
      try {
        r = await runCase(cases[i]);
      } catch (e) {
        console.log(`SPAWNFAIL idx=${i} ${String(e.code || e)}`);
        continue;
      }
      if (r.ok) pass++; else fails.push(r);
    }
  }
  await Promise.all(Array.from({ length: CONC }, worker));
  console.log(`[${label}] pass=${pass}/${cases.length} fail=${fails.length}`);
  for (const f of fails) {
    console.log('MISMATCH argv=[' + f.argv.map((a) => sig(a)).join(', ') + ']');
    console.log('  ref : code=' + f.ref.code + ' out=' + sig(f.ref.out, 200) + ' err=' + sig(f.ref.err, 400));
    console.log('  port: code=' + f.port.code + ' out=' + sig(f.port.out, 200) + ' err=' + sig(f.port.err, 400));
  }
  return fails;
}

