import { runCompact } from '/tmp/compact.mjs';

const A = (n, ch = 'a') => ch.repeat(n);
const rep = (n, v) => Array.from({ length: n }, () => v).join(',');

const cases = [];
// --- hrp length sweep around the observed 83-char limit, several program shapes
for (const n of [1, 2, 82, 83, 84, 85, 100, 200, 2000, 20000]) {
