  cases.push(['--a', A(n), '--b', '0', '--c', rep(20, '0')]);
  cases.push(['--a', A(n), '--b', '1', '--c', rep(40, '255')]);
  cases.push(['--a', A(n), '--b', '16', '--c', rep(32, '7')]);
