// mixed control chars + long
cases.push(['--a', '\x01\x02\x03\x1f\x7f'.repeat(20), '--b', '1', '--c', '0,0']);
cases.push(['--a', '\x01'.repeat(2000), '--b', '1', '--c', '0,0']);
cases.push(['--a', '\x7f'.repeat(20000), '--b', '1', '--c', '0,0']);

await runCompact(cases, 'hrp-stress');
